window.ScripturaLexicons.BDAG_PART_0245 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-01\" data-source=\"BDAG\" data-search=\"νῆσος, ου, ἡ substantivo feminino ilha; península BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νῆσος, ου, ἡ</td><td>substantivo feminino</td><td>ilha; península</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-02\" data-source=\"BDAG\" data-search=\"νηστεία, ας, ἡ substantivo feminino fome por privação; jejum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νηστεία, ας, ἡ</td><td>substantivo feminino</td><td>fome por privação; jejum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-03\" data-source=\"BDAG\" data-search=\"νηστεύω verbo jejuar; praticar o jejum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νηστεύω</td><td>verbo</td><td>jejuar; praticar o jejum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-04\" data-source=\"BDAG\" data-search=\"νῆστις, ὁ, ἡ adjetivo de dois gêneros sem comer; faminto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νῆστις, ὁ, ἡ</td><td>adjetivo de dois gêneros</td><td>sem comer; faminto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-05\" data-source=\"BDAG\" data-search=\"νηφαλέος remissão ver próximo verbete, νηφάλιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νηφαλέος</td><td>remissão</td><td>ver próximo verbete, νηφάλιος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-06\" data-source=\"BDAG\" data-search=\"νηφάλιος, ία, ον adjetivo sóbrio; moderado; equilibrado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νηφάλιος, ία, ον</td><td>adjetivo</td><td>sóbrio; moderado; equilibrado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-07\" data-source=\"BDAG\" data-search=\"νήφω verbo ser sóbrio; manter o autocontrole BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νήφω</td><td>verbo</td><td>ser sóbrio; manter o autocontrole</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-08\" data-source=\"BDAG\" data-search=\"νήχομαι verbo médio depoente nadar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νήχομαι</td><td>verbo médio depoente</td><td>nadar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-09\" data-source=\"BDAG\" data-search=\"Νίγερ, ὁ nome próprio masculino Níger; sobrenome de Simeão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νίγερ, ὁ</td><td>nome próprio masculino</td><td>Níger; sobrenome de Simeão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-10\" data-source=\"BDAG\" data-search=\"Νικάνωρ, ορος, ὁ nome próprio masculino Nicanor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικάνωρ, ορος, ὁ</td><td>nome próprio masculino</td><td>Nicanor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-11\" data-source=\"BDAG\" data-search=\"νικάω verbo vencer; superar; prevalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νικάω</td><td>verbo</td><td>vencer; superar; prevalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-12\" data-source=\"BDAG\" data-search=\"νίκη, ης, ἡ substantivo feminino vitória; meio de obter vitória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νίκη, ης, ἡ</td><td>substantivo feminino</td><td>vitória; meio de obter vitória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-13\" data-source=\"BDAG\" data-search=\"Νικήτης, ου nome próprio masculino Nicetes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικήτης, ου</td><td>nome próprio masculino</td><td>Nicetes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-14\" data-source=\"BDAG\" data-search=\"νικητής, ου, ὁ substantivo masculino; remissão crítica forma resultante de leitura incorreta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νικητής, ου, ὁ</td><td>substantivo masculino; remissão crítica</td><td>forma resultante de leitura incorreta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-15\" data-source=\"BDAG\" data-search=\"Νικόδημος, ου, ὁ nome próprio masculino Nicodemos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικόδημος, ου, ὁ</td><td>nome próprio masculino</td><td>Nicodemos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-16\" data-source=\"BDAG\" data-search=\"Νικολαί̈της, ου, ὁ substantivo masculino étnico nicolaíta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικολαί̈της, ου, ὁ</td><td>substantivo masculino étnico</td><td>nicolaíta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-17\" data-source=\"BDAG\" data-search=\"Νικόλαος, ου, ὁ nome próprio masculino Nicolau BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικόλαος, ου, ὁ</td><td>nome próprio masculino</td><td>Nicolau</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-18\" data-source=\"BDAG\" data-search=\"Νικόπολις, εως, ἡ nome próprio feminino; topônimo Nicópolis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νικόπολις, εως, ἡ</td><td>nome próprio feminino; topônimo</td><td>Nicópolis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-19\" data-source=\"BDAG\" data-search=\"νῖκος, ους, τό substantivo neutro vitória; prêmio da vitória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νῖκος, ους, τό</td><td>substantivo neutro</td><td>vitória; prêmio da vitória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0245-20\" data-source=\"BDAG\" data-search=\"Νινευή nome próprio feminino; topônimo Nínive BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νινευή</td><td>nome próprio feminino; topônimo</td><td>Nínive</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0245-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῆσος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νῆσος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições, papiros, LXX; PsSol 11:3; ParJer 9:19; EpArist; Philo, Aet. M. 120; 138; Jos., Ant. 4, 116 e outros; palavra emprestada ao rabínico), ilha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:26</a>. Chipre (Jos., Ant. 17, 335) 13:6. Malta 28:1, 7, 9, 11. Patmos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:9</a>. Deslocadas de seus lugares nos últimos dias 6:14; 16:20. Para a acepção «península», ver Warnecke, Romfahrt 67.—B. 29. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νηστεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νηστεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νηστεύω</span>; desde Hdt. 4, 186; papiros, LXX; Ps-Sol 3:8; Test12Patr, Philo, Joseph., Just.), «jejum».</p><p class=\"entry-text\">① Experiência de estar sem alimento suficiente, passar fome, em sentido geral, de fome causada pela necessidade: plural (B-D-F §142; W-S. §27, 4d; ver Rob. 408), de situações que se repetem frequentemente (cf. Da 9:3; 2 Macc 13:12): <span class=\"greek\">ἐν</span> <span class=\"greek\">νηστείαις</span>, passando fome <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:5</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">νηστείαις</span> <span class=\"greek\">πολλάκις</span>, frequentemente sem comida 11:27.</p><p class=\"entry-text\">② Ato de abster-se de alimentos para fins devocionais ou cultuais, jejum.</p><p class=\"entry-text\">ⓐ Jejuns públicos: acerca do Dia da Expiação (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">יוֹם</span> <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">כִּפּוּר</span>; Strabo 16, 2, 40 <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείας</span> <span class=\"greek\">ἡμέραν</span> [a respeito dos judeus]; Philo, Spec. Leg. 2, 193ff; Jos., Ant. 14, 66; 18, 94; Just., D. 40, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:9</a>; 7:4.—Para D 8:1, ver o final do verbete <span class=\"greek\">νηστεύω</span>.</p><p class=\"entry-text\">ⓑ Jejum privado Hs 5, 1, 3, final; 5, 2, 1; 5, 3, 5. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">συνή</span>̣<span class=\"greek\">θ</span>̣<span class=\"greek\">ι</span>̣<span class=\"greek\">α</span>̣[<span class=\"greek\">ν</span> <span class=\"greek\">τῆς</span>]| <span class=\"greek\">νη</span>̣[ … <span class=\"greek\">νη</span>]<span class=\"greek\">σ</span>̣<span class=\"greek\">τίας</span> (provavelmente ditografia e = <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">συνήθειαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νηστείας</span>), segundo o costume que tinham de jejuar AcPl Ha 7, 10f (contexto incerto). <span class=\"greek\">διὰ</span> [<span class=\"greek\">τ</span>]<span class=\"greek\">ὰ</span>̣<span class=\"greek\">ς</span> [<span class=\"greek\">νης</span>]<span class=\"greek\">τ</span>̣<span class=\"greek\">ί</span>̣<span class=\"greek\">α</span>̣<span class=\"greek\">ς</span> <span class=\"greek\">κ</span>̣<span class=\"greek\">α</span>̣[<span class=\"greek\">ὶ</span> <span class=\"greek\">τὰς</span>]| <span class=\"greek\">δι</span>[<span class=\"greek\">α</span>]<span class=\"greek\">νυκτερεύσις</span> … <span class=\"greek\">βα</span>̣<span class=\"greek\">ρηθεί</span>̣<span class=\"greek\">ς</span>, esgotado pelos jejuns e vigílias (com seus amigos) AcPl Ha 7, 25f. De Moisés no monte (com <span class=\"greek\">ταπείνωσις</span>; cf. Jdth 4:9 v.l.; Ps 34:13; PsSol 3:8) 1 Cl 53:2; semelhantemente, de Ester 55:6. (Com <span class=\"greek\">προσευχή</span>; cf. Tob 12:8; Da 9:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a> v.l. (<span class=\"greek\">νηστεία</span>, fortalecendo a oração, como em 2 Macc 13:12; Test Jos 10:1f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a> v.l. (Com <span class=\"greek\">δεήσεις</span>; cf. Da 9:3 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:37</a>. <span class=\"greek\">προσεύχεσθαι</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">νηστειῶν</span>, orar e jejuar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:23</a>. <span class=\"greek\">νηστείαν</span> <span class=\"greek\">νηστεύειν</span> (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">צוּם</span> <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">צוֹם</span> 2 Km 12:16; 3 Km 20:9), guardar, observar um jejum Hs 5, 1, 2f; <span class=\"greek\">νηστεύειν</span> <span class=\"greek\">τήν</span> <span class=\"greek\">ν</span>., guardar o jejum (o dia de jejum) 7:3 (<span class=\"greek\">ἡ</span> <span class=\"greek\">νηστεία</span> = dia de jejum, como em Jos., Ant. 18, 94). <span class=\"greek\">νηστεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">νηστείαν</span>, observar jejum para Deus Hs 5, 1, 4b (Just., D. 15, 1). <span class=\"greek\">μεγάλην</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ποιεῖν</span> 5, 1, 5. <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span> 5, 3, 5; <span class=\"greek\">τελεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ν</span>. 5, 3, 8. <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τελεία</span> 5, 3, 6, segundo Hermas, inclui abster-se de todo mal, além de abster-se de alimento. <span class=\"greek\">τιμίαν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ν</span>. AcPl Ha 6, 25 (cf. Just., D. 15, 1 <span class=\"greek\">ἀληθινήν</span> … <span class=\"greek\">ν</span>.).—<span class=\"greek\">προσκαρτερεῖν</span> <span class=\"greek\">νηστείαις</span>, perseverar em jejuns Pol 7:2. <span class=\"greek\">ἀποθέσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span>, encerrar o jejum AcPl Ha 6, 37. O jejum é considerado superior à oração 2 Cl 16:4 (cf. Tob 12:8f). Rejeitado por Deus 3:1ff (Is 58:5f). <span class=\"greek\">τῆς</span> <span class=\"greek\">νηστείας</span> <span class=\"greek\">εἰρωνεία</span>, observância afetada dos dias de jejum Dg 4:1.—RArbesmann, D. Fasten b. d. Griech. u. Römern 1929; MFreiberger, D. Fasten im alten Israel 1929; JMontgomery, Ascetic Strains in Early Judaism: JBL 51, ’32, 183–213; IAbrahams, Studies in Pharisaism and the Gospels I 1917, 121–28; GMoore, Judaism II 1927, 55ff; 257ff; Billerb. IV 1928, 77–114: V. altjüd. Fasten; MShepherd, ATR 40, ’58, 81–94; RAC VII 447–93.—DELG s.v. 1 <span class=\"greek\">νῆστις</span>. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νηστεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νηστεύω</span>, particípio presente feminino plural, forma alternativa <span class=\"greek\">νηστέουσαι</span> (AcPl Ha 5, 19f); futuro <span class=\"greek\">νηστεύσω</span>; 1º aoristo <span class=\"greek\">ἐνήστευσα</span>, infinitivo <span class=\"greek\">νηστεῦσαι</span>, imperativo <span class=\"greek\">νηστεύσατε</span>, particípio <span class=\"greek\">νηστεύσας</span>; perfeito, 2ª pessoa do plural <span class=\"greek\">νενηστεύκατε</span> Zech 7:5 (Aristoph.; Aristot.; Plut., Mor. 626f; Aelian, VH 5, 20; LXX; Test12Patr; ApcEsdr 1:3 p. 24, 9 Tdf. e frequentemente; Philo, Spec. Leg. 2, 197; Jos., C. Ap. 1, 308; Ar. [Milne 76, verso 1]; Just.), jejuar como rito devocional entre judeus e cristãos: como sinal de pesar (2 Km 1:12; 12:22; Zech 7:5; Bar 1:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a>f (cf. <span class=\"greek\">ν</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ἐκείνῃ</span> Judg 20:26; 1 Km 7:6); 7:5; AcPl Ha 5, 19f; GPt 7:27. Moisés B 4:7; 14:2 (quanto à ideia, cf. Ex 34:28) e Jesus (Iren. 3, 22, 2 [Harv. II 122, 6]; Did., Gen. 190, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:2</a> jejuam durante quarenta dias e quarenta noites (cf. 1 Km 31:13; 1 Ch 10:12 <span class=\"greek\">ν</span>. <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἡμέρας</span>; Marinus, Vi. Procli 19 Boiss. <span class=\"greek\">τινὰς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἡμέρας</span>). Com lamentação 7:5. Sobre José GJs 1:4. Como preparação para a oração (Jos., Ant. 20, 89) Hv 3, 10, 6; para o batismo D 7:4 (sobre o jejum antes da admissão nos cultos de mistérios greco-romanos, ver Knopf, Hdb. ad loc.). Com <span class=\"greek\">προσεύχεσθαι</span> (cf. Bar 1:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:3</a>. Com <span class=\"greek\">δέομαι</span> Hv 3, 1, 2. Com <span class=\"greek\">εὐχαριστεῖν</span> 5, 1, 1. Para intensificar a eficácia de sua oração, Hermas jejua <span class=\"greek\">μίαν</span> <span class=\"greek\">ἡμέραν</span>, durante um dia inteiro 3, 10, 7; jejum de quinze dias 2, 2, 1. Seu jejum consiste em consumir apenas pão e água Hs 5, 3, 7. Com <span class=\"greek\">λειτουργεῖν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:2</a> (EPeterson, Nuntius 2, ’49, 9f). Jesus e seus discípulos não jejuam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:33</a> (HEbeling, D. Fastenfrage [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:18</a>–22]: StKr 108, ’37/38, 387–96, mas ver KSchäfer, Synopt. Studien [Wikenhauser Festschr.], ’53, 124–47; FCremer, D. Fastenansage Jesu, ’65). Atitudes corretas e incorretas no jejum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:16</a>–18. <span class=\"greek\">ν</span>. <span class=\"greek\">νηστείαν</span>, observar um jejum Hs 5, 1, 2f (ver <span class=\"greek\">νηστεία</span> 2b). <span class=\"greek\">ν</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">νηστείαν</span> 5, 1, 4b; em oposição a <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">νηστεύσῃ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span>, <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">ἐξολεθρευθήσεται</span>, aquele que não observa o dia de jejum sofrerá a pena de morte 7:3 (ver <span class=\"greek\">νηστεία</span> 2b). <span class=\"greek\">ν</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> Hs 5, 1, 3; 5, 1, 4a; cf. 3:1 (Is 58:4). Como ato agradável a Deus (Hs 5, 3, 7), indicando-se a pessoa que dele se beneficiará: <span class=\"greek\">νηστεύετε</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">διωκόντων</span> <span class=\"greek\">ὑμᾶς</span>, jejuai por aqueles que vos perseguem D 1:3 (onde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> tem <span class=\"greek\">προσεύχεσθε</span>.—Knopf, Hdb. ad loc.). Israelitas piedosos costumavam jejuar duas vezes por semana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>, na segunda e na quinta-feira (ver Schürer II 483f; Elbogen 126f; 225f; 533; 551; Billerb. acerca de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>), e os cristãos na quarta e na sexta-feira D 8:1.—<span class=\"greek\">ν</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> Ox 1, verso 5–6 (ASyn. 54, 22; cf. GTh 27) ainda não foi explicado satisfatoriamente. Poderia ser tomado figuradamente, abster-se do mundo (ver s.v. <span class=\"greek\">νηστεία</span> 2b acerca de Hs 5, 3, 6 e cf. Empedocles em Plut., Mor. 464b [Vorsokrat. I5 369, 17] <span class=\"greek\">νηστεῦσαι</span> <span class=\"greek\">κακότητος</span>; LWright, JBL 65, ’46, 180)?—B. 1483. DELG s.v. 1 <span class=\"greek\">νῆστις</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῆστις, ὁ, ἡ</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νῆστις</span>, <span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νη</span>- privativo, <span class=\"greek\">ἔδω</span> «comer»), genitivo no jônico e épico <span class=\"greek\">ιος</span>, no ático <span class=\"greek\">ιδος</span>, acusativo plural <span class=\"greek\">νήστεις</span> (ver B-D-F §47, 3; Mlt-H. 132 [estritamente deve ser chamado de adjetivo]; 287; 374; sobre a formação da palavra, Wackernagel, Kl. Schr. 1150), que não come, faminto (assim desde Hom.; Da 6:19 [PKatz, TLZ 81, ’56, 605]; cf. JosAs 13:8 cód. A [p. 57, 16 Bat.] <span class=\"greek\">νήστης</span> <span class=\"greek\">ὑπάρχω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:3</a>.—DELG s.v. 1 <span class=\"greek\">νῆστις</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νηφαλέος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νηφαλέος</span>: ver o verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νηφάλιος, ία, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νηφάλιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">νήφω</span>; Aeschyl. e outros; Plut.; SIG 1040, 26), forma tardia <span class=\"greek\">νηφαλέος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (variante de leitura; Herodian Gr. I 114, 17 e outros; Philo, Leg. All. 3, 82; Etym. Mag. p. 261, 52; 262, 2; AcJ 69 [p. 184, 10]. Sobre o acento, ver Kühner-Bl. II p. 297, 11; B-D-F §35, 3; Mlt-H. 76; 362), a respeito de pessoas (cf. Philo, Sobr. 2, Mos. 1, 187; Jos., Ant. 3, 279).</p><p class=\"entry-text\">① Relativo a ser muito moderado no consumo de bebida alcoólica, moderado, sóbrio (assim Dibelius/Conzelmann, comentário Hermeneia ad loc. Sobre a moderação no consumo de vinho, ver Theognis 467–510. Sobre a proibição de bebidas fortes aos sacerdotes em exercício das funções oficiais, ver Lev 10:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:2</a> (em oposição a <span class=\"greek\">πάροινος</span>, versículo 3. O último termo aparece numa série composta principalmente de negações, em contraste com as virtudes positivas do versículo 2), 11 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:3</a> e a figura estereotipada da «anus» [«bruxa velha»] dada à bebida na literatura latina: Ovid, Fasti 3, 765f e outros; VRoswach, Classical World 88, ’94, 113f; Arnott, Alexis p. 504) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:2</a>. Outros interpretam metaforicamente.</p><p class=\"entry-text\">② Relativo a comportamento moderado, com domínio de si, equilibrado, extensão figurada de 1 (ver próximo verbete): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:2</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:2</a>.—DELG s.v. <span class=\"greek\">νήφω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νήφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νήφω</span>, 1º aoristo <span class=\"greek\">ἔνηψα</span> (Soph., Pla., X. e outros; inscrições, papiros), primariamente «estar sóbrio»; no NT somente figuradamente = estar livre de toda forma de «embriaguez» mental e espiritual, de excessos, paixões, precipitação, confusão etc.; ser equilibrado, exercer autocontrole (Aristot. e outros; Epicurus em Diog. L. 10, 132 <span class=\"greek\">νήφων</span> <span class=\"greek\">λογισμός</span> = ponderação sóbria; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 16, 4; Lucian, Hermot. 47 <span class=\"greek\">νῆφε</span>; Herodian 2, 15, 1; Achilles Tat. 1, 13 <span class=\"greek\">ν</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κακοῦ</span>; Herm. Wr. 7, 1; BGU 1011 III, 9 [II b.c.]; POxy 1062, 13 <span class=\"greek\">ἵνα</span> <span class=\"greek\">αὐτὴν</span> [sc. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπιστολὴν</span>] <span class=\"greek\">ἀναγνοῖς</span> <span class=\"greek\">νήφων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σαυτοῦ</span> <span class=\"greek\">καταγνοῖς</span>; EpArist 209; Philo; Jos., Bell. 2, 225; 4, 42; SibOr 1, 154) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:13</a>. [<span class=\"greek\">Ἱερώνυμος</span> <span class=\"greek\">ἤδ</span>]<span class=\"greek\">η</span>̣ <span class=\"greek\">νήψας</span> <span class=\"greek\">νυκτὸς</span> | <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀδύνα</span>̣[<span class=\"greek\">ις</span>], Hierônimo, afligido pela dor (de uma lesão no ouvido durante uma tempestade violenta), recuperou a lucidez durante a noite (quanto à sua animosidade contra Paulo) AcPl Ha 5, 29f. <span class=\"greek\">ν</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, manter o autocontrole em todas as circunstâncias (M. Ant. 1, 16, 15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:5</a>. Com <span class=\"greek\">γρηγορεῖν</span> (cf. Plut., Mor. 800b <span class=\"greek\">ἀγρυπνῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">νήφων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πεφροντικώς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:8</a>. Com <span class=\"greek\">σωφρονεῖν</span> (Lucian, Nigrin. 5f): <span class=\"greek\">ν</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">προσευχάς</span>, exercer autocontrole para auxiliar a oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:7</a>; Pol 7:2 tem <span class=\"greek\">ν</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">εὐχάς</span>. <span class=\"greek\">ν</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span>, exercer autocontrole para o próprio bem 2 Cl 13:1. Com alusão ao autocontrole praticado por atletas: <span class=\"greek\">νῆφε</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀθλητής</span> IPol 2:3.—HLevy, Sobria ebrietas 1929.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νήχομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νήχομαι</span>, médio depoente (Hom. e outros; Hero Alex. I 414, 18; 446, 16; Plut.; Lucian; Job 11:12 [?]; Philo Epicus Jud. [II b.c.]: 729 Fgm. 2 verso 1 Jac. [em Eus., PE 9, 37, 1]; Philo Alex., De Prov. Fgm. 2 [em Eus., PE 8, 14, 65]; Jos., Ant. 15, 55, Vi. 15), nadar: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βυθῷ</span> 10:5.—B. 681. DELG s.v. 1 <span class=\"greek\">νέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νίγερ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νίγερ</span>, <span class=\"greek\">ὁ</span> (GDI 1555c, 20; e, 24 [Phocis]; óstraco APF 6, 1920, 213, 1 [174/75 a.d.] <span class=\"greek\">Αἰβύτιος</span> <span class=\"greek\">Νίγερ</span>; Sb 46; 8808, 3 [época imperial]; O. Wilck II, 266; 296; tabuinha de madeira com o nome do veterano L. Petronius Niger [94 a.d.] em Dssm., LO 383 [LAE 443]; Jos., Bell. 2, 520), Níger (cf. latim niger = «de tez escura»), sobrenome de Simeão, o profeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικάνωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικάνωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (Thu. 2, 80, 5 e outros; OGI 21, 4; 196, 11f; 599, 1 e outros em inscrições; Sb 1079; 3763; PFrankf 5 recto, 20 [242/241 b.c.]; 1, 2 e 4 Macc; EpArist 182; Joseph.—B-D-F §29, 3. No rabínico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נִיקָנוֹר</span>), nome encontrado frequentemente, Nicanor, um dos sete auxiliares da congregação de Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νικάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νικάω</span> (Hom. e outros; inscrições, papiros, LXX; PsSol 4:10; TestJob 27:5; Test12Patr, Philo, Joseph., Just., Tat.; Ath. 3, 2), particípio <span class=\"greek\">νικῶν</span>, dativo <span class=\"greek\">νικῶντι</span> ou <span class=\"greek\">νικοῦντι</span> (assim algumas edições em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a>, em parte também no versículo 7; acerca da alternância de formas em -<span class=\"greek\">άω</span> e -<span class=\"greek\">έω</span>, ver B-D-F §90; W-S. §13, 26; Rob. 203; ver Mlt-H. 195); futuro <span class=\"greek\">νικήσω</span>; 1º aoristo <span class=\"greek\">ἐνίκησα</span>; perfeito <span class=\"greek\">νενίκηκα</span>. Passivo: infinitivo do 1º futuro <span class=\"greek\">νικηθήσεσθαι</span> (Just., D. 78, 9); 1º aoristo <span class=\"greek\">ἐνικήθην</span> LXX, particípio <span class=\"greek\">νικηθείς</span>; infinitivo perfeito <span class=\"greek\">νενικῆσθαι</span> 4 Macc 13:2.</p><p class=\"entry-text\">① Vencer diante de obstáculos, ser vencedor, conquistar, superar, prevalecer, intransitivo.</p><p class=\"entry-text\">ⓐ Numa batalha ou competição (EpArist 281); de Israel vitorioso na batalha 12:2 (cf. Ex 17:11); de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:21</a>b; 5:5 (o infinitivo seguinte <span class=\"greek\">ἀνοῖξαι</span> indica o que a vitória permite ao vencedor fazer). <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">νικῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">νικήσῃ</span> 6:2. Do bom atleta (Lucian, Tim. 50; POxy 1759, 4, carta a um atleta) IPol 3:1. O cristão como <span class=\"greek\">ὁ</span> <span class=\"greek\">νικῶν</span>, aquele que vence (ver B-D-F §322; Rob. 865) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:7</a>, 11, 17, 26; 3:5, 12, 21; 21:7 (ver Boll 49, 1). <span class=\"greek\">οἱ</span> <span class=\"greek\">νικῶντες</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θηρίου</span> (=<span class=\"greek\">τηρήσαντες</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>.—B-D-F §212; GBonaccorsi, Primi saggi di filologia neotest. I ’33 p. clxii) 15:2.—Hs 8, 3, 6 v.l.</p><p class=\"entry-text\">ⓑ Numa ação judicial (Aristoph., Equ. 95, Av. 445; 447; Protagoras em Diog. L. 9, 56 [<span class=\"greek\">νικάω</span> e <span class=\"greek\">νίκη</span>]; Artem. 1, 35 p. 36, 20; 4, 31 p. 222, 17 e outros; PSI 551, 7 [III b.c.] <span class=\"greek\">ἐνίκων</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κρίσει</span>; PHal 1, 51; 58 [III b.c.]; Jos., Bell. 2, 284, Ant. 12, 126): <span class=\"greek\">ὅπως</span> … <span class=\"greek\">και</span> <span class=\"greek\">νικήσεις</span> (variante de leitura <span class=\"greek\">νικήσῃς</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρίνεσθαί</span> <span class=\"greek\">σε</span>, para que venças quando fores acusado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a>; 1 Cl 18:4 (ambos Ps 50:6.—IG XI/4, 1299, 26f [c. 200 b.c.] Serápis e seus adoradores vencem processo judicial acerca de um novo templo [tradução inglesa em Danker, Benefactor, nº 27]).</p><p class=\"entry-text\">② Superar alguém, derrotar, vencer, transitivo.</p><p class=\"entry-text\">ⓐ Voz ativa, com objeto no acusativo: <span class=\"greek\">τινά</span>, vencer alguém (Polyb. 6, 58, 13; Diod S 4, 57, 6; Jos., Vi. 81) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>; 13:7; 17:14. De Cristo: <span class=\"greek\">νενίκηκα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, venci o mundo (isto é, a totalidade de tudo o que se opõe a Deus; ver <span class=\"greek\">κόσμος</span> 7b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:33</a>b (<span class=\"greek\">ν</span>. <span class=\"greek\">τι</span> = «ser mais forte que»: IAndros Isis, Kyme 55 p. 124). Também dito dos cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4</a>f; cf. <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">νίκη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">νικήσασα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, versículo 4b (ver <span class=\"greek\">νίκη</span>). Também <span class=\"greek\">ν</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">πονηρόν</span>, vencer o Maligno, o diabo 2:13f (sobre esta passagem e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:33</a>b ver JBruns, JBL 86, ’67, 451–53); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:11</a>. <span class=\"greek\">αὐτόν</span> (=<span class=\"greek\">τὸν</span> <span class=\"greek\">διάβολον</span>) Hs 8, 3, 6. <span class=\"greek\">αὐτούς</span> (=<span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:4</a>. <span class=\"greek\">ν</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>, obter vitória sobre a alma (isto é, a parte da pessoa voltada para as coisas terrenas; cf. Sextus 71a <span class=\"greek\">νίκα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>) 2 Cl 16:2. Com a força pela qual se conquista acrescentada no dativo: por meio de <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Pla., Symp. 213e; Himerius, Or. [Ecl.] 3, 11 <span class=\"greek\">ἐν</span> <span class=\"greek\">δόγμασι</span> <span class=\"greek\">νικῶν</span> <span class=\"greek\">ἐκείνους</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπιθυμίας</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πονηράς</span>, por não praticar seus desejos vis 2 Cl 16:2. <span class=\"greek\">ν</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀγαθῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span>, vencer o mal com o bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:21</a>b (TestBenj 4:3 <span class=\"greek\">οὗτος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ποιῶν</span> <span class=\"greek\">νικᾷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span>).</p><p class=\"entry-text\">ⓑ Voz passiva: ser conquistado, derrotado (Thu. 1, 76, 2 e outros; Posidippus [III b.c.]: 447 Fgm. 2 Jac. <span class=\"greek\">νικᾶται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Κύπριος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σχήματι</span> = o cipriota é «vencido» pelo retrato [de Afrodite], e outros; Philo, De Jos. 200 <span class=\"greek\">νικώμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάθους</span>; Jos., Ant. 1, 302, pela força da necessidade; Tat. 9, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">νικώμενος</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">εἰσαῦτις</span> <span class=\"greek\">ἐπικρατεῖν</span> <span class=\"greek\">εἴωθεν</span>; Theoph. Ant. 2, 12 [p. 130, 30] <span class=\"greek\">θεὸν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">χρὴ</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἡδονῆς</span> <span class=\"greek\">νικᾶσθαι</span>) Hm 12, 5, 2. <span class=\"greek\">ὁ</span> <span class=\"greek\">πονηρὸς</span> … <span class=\"greek\">νικηθείς</span> AcPlCor 2:15. Deixar-se vencer: <span class=\"greek\">μὴ</span> <span class=\"greek\">νικῶ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κακοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:21</a>a; Dg 7:7.</p><p class=\"entry-text\">③ Superar em capacidade, ultrapassar, exceder, transitivo, com a força superior acrescentada no dativo (cf. Eur., Herc. Fur. 342 <span class=\"greek\">ἀρετῇ</span>; Ael. Aristid. 13 p. 272 D.: <span class=\"greek\">ἐπιεικείᾳ</span>; Tat. 15:4 <span class=\"greek\">θανάτῳ</span> … <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">νενικήκασιν</span>): <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἰδίοις</span> <span class=\"greek\">βίοις</span> <span class=\"greek\">νικῶσι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νόμους</span>, pelo seu modo de vida superam (ou excedem) as leis (isto é, vivem melhor do que as leis exigem) Dg 5:10.—DELG s.v. <span class=\"greek\">νίκη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νίκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νίκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições, papiros, LXX; TestSol 10:9 C; TestJob 1:3 [nome próprio]; SibOr 13, 38; EpArist 180; Philo, Leg. All. 3, 186 <span class=\"greek\">ὅταν</span> <span class=\"greek\">νικήσῃ</span> <span class=\"greek\">νίκην</span>; Jos., Ant. 6, 145 e outros; Tat. 19, 3), vitória; depois, por uso do abstrato em lugar do concreto, meio para obter uma vitória (mas cf. também o costume de falar da <span class=\"greek\">νίκη</span> do imperador; «victoria» como atributo do imperador em moedas: Coins of the Roman Empire in the British Museum, ed. Mattingly, I 241, no. 214 [Nero]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4</a>.—B. 1406. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικήτης, ου</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικήτης</span>, <span class=\"greek\">ου</span>, nome bastante comum (SIG 287, 2; 491, 73; 540, 44; 1029, 62), Nicetes MPol 8:2; 17:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νικητής, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; remissão crítica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νικητής</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, em uma leitura incorreta de AcPl Ox 1602, verso 30; ver <span class=\"greek\">μένω</span> 1b.—DELG s.v. <span class=\"greek\">νίκη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικόδημος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικόδημος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, nome comum entre judeus e gentios (exemplos em Wettstein; Diod S 16, 82; 4; Jos., Ant. 14, 37; SIG2 e Preisigke, Sb, nos índices; PHib 110, 60; 75; 105; PFlor 6, 20 <span class=\"greek\">Νικόδημος</span> <span class=\"greek\">βουλευτής</span>), Nicodemos (no rabínico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נַקְדֵּימוֹן</span>), membro do Sinédrio que era favorável a Jesus e à sua causa, mencionado somente em J. Pouco se sabe a seu respeito, e é duvidosa a ligação com o Nicodemos talmúdico, cujo verdadeiro nome teria sido Buni ben Gorion e que era tido como discípulo de Jesus (Billerb. II 413f). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:1</a>, 4, 9; 7:50; 19:39.—BZimolong, D. Nikod. perikope (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:23</a>–3:22) nach d. syrosinait. Text, dissertação Bresl. 1919; SMendner, JBL 77, ’58, 293–323.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικολαί̈της, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino étnico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικολαί</span>̈<span class=\"greek\">της</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, nicolaíta, substantivo étnico (sobre a forma, ver Mussies 151), seguidor de Nicolau, fundador de seita que, afora isso, é desconhecido; <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Νικολαϊτῶν</span>, obras dos nicolaítas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:6</a>. <span class=\"greek\">διδαχὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Νικολαϊτῶν</span>, doutrina dos nicolaítas, versículo 15. Sobre a seita dos nicolaítas, ver ESchürer, Die Prophetin Isabel: Weizsäcker Festschr. 1892, 39–58; LSeesemann, StKr 66, 1893, 47–82; GWohlenberg, NKZ 6, 1895, 923ff; Zahn, Einl. II3 623f; AvHarnack, The Sect of the Nicolaitans and Nicolaus, the Deacon in Jerus.: JR 3, 1923, 413–22; MGoguel, Les Nicolaïtes: RHR 115, ’37, 5–36; NBrox, Nikolaos u. Nikolaitan, VigChr 19, ’65, 23–30.—Cf. DELG s.v. <span class=\"greek\">νίκη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικόλαος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικόλαος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt. e outros; Diod S 13, 19, 6; 32, 15, 5; IG XIV, 682; 1252; SIG2 e Preisigke, Sb, índices; Joseph.), Nicolau, prosélito de Antioquia e um dos sete auxiliares da igreja de Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>. Parece pouco provável que ele tivesse alguma coisa a ver com a seita dos nicolaítas, apesar das afirmações dos antigos (aceitas por Zahn) nesse sentido.—DELG s.v. <span class=\"greek\">νίκη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νικόπολις, εως, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νικόπολις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span>, Nicópolis; dentre as numerosas cidades que tinham esse nome (Stephan. Byz. menciona três delas, no Épiro, na Bitínia e na Armênia Menor), aquela mencionada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:12</a> e na subscrição de 1 Ti e Tit geralmente é considerada a <span class=\"greek\">Ν</span>. do Épiro (atual Smyrtoula), fundada por Otaviano como monumento à sua vitória sobre Marco Antônio em 31 b.c. em Áccio (Cass. Dio 50, 13; 51, 1; Strabo 7, 7, 5; 10, 2, 2).—Pauly-W. XVII 511–39; Kl. Pauly IV 123–26; MDibelius, Hdb. excursus em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:14</a>; PECS 625f.—DELG s.v. <span class=\"greek\">νίκη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῖκος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νῖκος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Manetho, Apot. 1, 358; Orph., Argon. 587; Polemo 1, 12 p. 6, 16; Vett. Val. 358, 5; IG XII/5, 764, 2; BGU 1002, 14 [55 b.c.]; LXX; SibOr 14, 334; 339; Lob. acerca de Phryn. p. 647), forma tardia em lugar de <span class=\"greek\">ἡ</span> <span class=\"greek\">νίκη</span> (JWackernagel, Hellenistica 1907, 26f; EFraenkel, Glotta 4, 1913, 39ff; B-D-F §51, 1; Mlt-H. 126; 381).</p><p class=\"entry-text\">① Vitória: <span class=\"greek\">ποῦ</span> <span class=\"greek\">σου</span> <span class=\"greek\">θάνατε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ν</span>.; onde está, ó Morte, a tua vitória? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.55\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:55</a>a (segundo Hos 13:14, onde os nossos manuscritos da LXX leem <span class=\"greek\">ποῦ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δίκη</span> <span class=\"greek\">σου</span>, <span class=\"greek\">θ</span>. [ver WDittmar, V.T. in Novo 1903, 217 e ver <span class=\"greek\">κέντρον</span> 1], mas Paulo, influenciado pelo versículo 54, emprega <span class=\"greek\">νῖκος</span> no lugar de <span class=\"greek\">δίκη</span>; EEllis, Paul’s Use of the OT, ’57, 140). Em <span class=\"greek\">κατεπόθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θάνατος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">νῖκος</span>, a morte foi tragada na (ou pela) vitória, versículo 54, <span class=\"greek\">νῖκος</span> concorda com o aperfeiçoamento que Theod. fez na formulação da LXX de Is 25:8 (ver ARahlfs, ZNW 20, 1921, 183f; JZiegler, Is. ’39 ad loc.). Os versículos 54 e 55 apresentam a variante de leitura <span class=\"greek\">νεῖκος</span>, q.v. <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ν</span>., conceder a alguém a vitória, versículo 57 (cf. 1 Esdr 3:9; 2 Macc 10:38; Jos., Ant. 6, 145). <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἐκβάλῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span>, até que conduza a justiça à vitória <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a> (cf. 2 Km 2:26 e variantes em Field, Hexapla e na LXX de Cambridge; ver <span class=\"greek\">κρίσις</span>, final).</p><p class=\"entry-text\">② Prêmio da vitória, emprego do abstrato pelo concreto (4 Macc 17, 12 <span class=\"greek\">τὸ</span> <span class=\"greek\">νῖκος</span> <span class=\"greek\">ἀφθαρσία</span>): <span class=\"greek\">παραδοὺς</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">ἔλαβες</span>, entregar a ela o prêmio da vitória que obtiveste Hm 12, 2, 5 (talvez se deva subentender antes na frase uma expressão como <span class=\"greek\">νῖκος</span> <span class=\"greek\">λαβών</span>).—DELG s.v. <span class=\"greek\">νίκη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0245-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νινευή</h1><div class=\"entry-meta\"><span>nome próprio feminino; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νινευή</span> (forma inferior <span class=\"greek\">Νινευί</span> [B-D-F §39, 1; ver Rob. 191f]), <span class=\"greek\">ἡ</span>, indeclinável (Gen 10:11f; Is 37:37; Jon 1:2 e outros; Zeph 2:13 e outros na LXX; ViJon 2f [p. 83, 29 Sch.]; hebraico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נִינְוֵה</span>), Nínive, capital do império assírio posterior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:32</a> v.l.; AcPlCor 2:29.</p></section></article>\n"};
